with feeders as (
    select
        md5(upper('HUB_RISK_OBJECT|' || (HUB_RISK_OBJECT_BK__CONTRACT_ID_MEMBER_ID))) as HUB_RISK_OBJECT_HK
        , cast(null as varchar) as SELF_COVERED_INDICATOR
        , cast(null as varchar) as CLAIM_REGISTERED_INDICATOR
        , cast(null as varchar) as BASE_SUM_INSURED
        , cast(null as varchar) as BALANCE_SUM_INSURED_AMOUNT
        , MEDICAL_REPORT as MEDICAL_REPORT_RECEIVED_INDICATOR
        , INCEPTION_DATE as MEMBER_COVER_INCEPTION_DATE
        , HC_RATE_STATUS as MEMBER_RATING_STATUS
        , HC_WAITING_PERIOD as HEALTH_COVER_BENEFIT_WAITING_PERIOD
        , REMARK_ENROLLMENT as ENROLMENT_REMARKS
        , GMC_METRO as METRO_CLASSIFICATION
        , HC_BENEFIT_OPTED as BENEFIT_OPTION_CODE
        , HC_HOSPITAL as NETWORK_HOSPITAL_REFERENCE
        , IHG_WAITING_PERIOD as INDIVIDUAL_HEALTH_PRODUCT_WAITING_PERIOD
        , 'BJAZ_HM_MEMBER_HLTH_DTLS' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_member_hlth_dtls') }}
    where (nullif('MEMBER:' || coalesce(nullif(trim(CONTRACT_ID),''),'') || '#' || coalesce(nullif(trim(MEMBER_ID),''),''), 'MEMBER:#')) is not null
),

resolved as (
    select
        HUB_RISK_OBJECT_HK,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then SELF_COVERED_INDICATOR end) as SELF_COVERED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then CLAIM_REGISTERED_INDICATOR end) as CLAIM_REGISTERED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BASE_SUM_INSURED end) as BASE_SUM_INSURED,
        max(case when SOURCE_RUN = 'opus_health_legacy_v4' then BALANCE_SUM_INSURED_AMOUNT end) as BALANCE_SUM_INSURED_AMOUNT,
        max(case when SOURCE_RUN = 'opus_health_v2' then MEDICAL_REPORT_RECEIVED_INDICATOR end) as MEDICAL_REPORT_RECEIVED_INDICATOR,
        max(case when SOURCE_RUN = 'opus_health_v2' then MEMBER_COVER_INCEPTION_DATE end) as MEMBER_COVER_INCEPTION_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then MEMBER_RATING_STATUS end) as MEMBER_RATING_STATUS,
        max(case when SOURCE_RUN = 'opus_health_v2' then HEALTH_COVER_BENEFIT_WAITING_PERIOD end) as HEALTH_COVER_BENEFIT_WAITING_PERIOD,
        max(case when SOURCE_RUN = 'opus_health_v2' then ENROLMENT_REMARKS end) as ENROLMENT_REMARKS,
        max(case when SOURCE_RUN = 'opus_health_v2' then METRO_CLASSIFICATION end) as METRO_CLASSIFICATION,
        max(case when SOURCE_RUN = 'opus_health_v2' then BENEFIT_OPTION_CODE end) as BENEFIT_OPTION_CODE,
        max(case when SOURCE_RUN = 'opus_health_v2' then NETWORK_HOSPITAL_REFERENCE end) as NETWORK_HOSPITAL_REFERENCE,
        max(case when SOURCE_RUN = 'opus_health_v2' then INDIVIDUAL_HEALTH_PRODUCT_WAITING_PERIOD end) as INDIVIDUAL_HEALTH_PRODUCT_WAITING_PERIOD,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_RISK_OBJECT_HK
),

hashed as (
    select
        *,
        case when SELF_COVERED_INDICATOR is not null or CLAIM_REGISTERED_INDICATOR is not null or BASE_SUM_INSURED is not null or BALANCE_SUM_INSURED_AMOUNT is not null or MEDICAL_REPORT_RECEIVED_INDICATOR is not null or MEMBER_COVER_INCEPTION_DATE is not null or MEMBER_RATING_STATUS is not null or HEALTH_COVER_BENEFIT_WAITING_PERIOD is not null or ENROLMENT_REMARKS is not null or METRO_CLASSIFICATION is not null or BENEFIT_OPTION_CODE is not null or NETWORK_HOSPITAL_REFERENCE is not null or INDIVIDUAL_HEALTH_PRODUCT_WAITING_PERIOD is not null
                     then md5(upper(coalesce(cast(SELF_COVERED_INDICATOR as varchar), '') || '|' || coalesce(cast(CLAIM_REGISTERED_INDICATOR as varchar), '') || '|' || coalesce(cast(BASE_SUM_INSURED as varchar), '') || '|' || coalesce(cast(BALANCE_SUM_INSURED_AMOUNT as varchar), '') || '|' || coalesce(cast(MEDICAL_REPORT_RECEIVED_INDICATOR as varchar), '') || '|' || coalesce(cast(MEMBER_COVER_INCEPTION_DATE as varchar), '') || '|' || coalesce(cast(MEMBER_RATING_STATUS as varchar), '') || '|' || coalesce(cast(HEALTH_COVER_BENEFIT_WAITING_PERIOD as varchar), '') || '|' || coalesce(cast(ENROLMENT_REMARKS as varchar), '') || '|' || coalesce(cast(METRO_CLASSIFICATION as varchar), '') || '|' || coalesce(cast(BENEFIT_OPTION_CODE as varchar), '') || '|' || coalesce(cast(NETWORK_HOSPITAL_REFERENCE as varchar), '') || '|' || coalesce(cast(INDIVIDUAL_HEALTH_PRODUCT_WAITING_PERIOD as varchar), '')))
                end as SAT_RISK_HEALTH_MEMBER_COVERAGE_HASHDIFF
    from resolved
)

